/******************CREATE LT CLEAN PROCEDURE********************/ CREATE PROCEDURE "DA_CA_BPNN_CLEAN" (IN SchemaName VARCHAR(100)) LANGUAGE SQLSCRIPT  SQL SECURITY INVOKER  AS BEGIN     DECLARE ROWCNT INTEGER;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_CA_PAL_NN_TRAIN' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         CALL SYS.AFLLANG_WRAPPER_PROCEDURE_DROP(:SchemaName, 'DA_CA_PAL_NN_TRAIN');     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_CA_PAL_NN_PREDICT' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         CALL SYS.AFLLANG_WRAPPER_PROCEDURE_DROP(:SchemaName, 'DA_CA_PAL_NN_PREDICT');     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_CA_PAL_NN_CREATE_WRAPPER' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP PROCEDURE "DA_CA_PAL_NN_CREATE_WRAPPER"';     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_CA_PAL_NN_PREDICTION' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP PROCEDURE "DA_CA_PAL_NN_PREDICTION"';     END IF; END
